Object.assign(ru,{heroTitle:'Профессиональная уборка для дома и бизнеса в Ташкенте',heroText:'Убираем квартиры, дома, офисы и коммерческие объекты силами профессиональных сотрудников. Рассчитайте стоимость или получите бесплатную консультацию.',checked:'Профессиональные сотрудники',years:'лет опыта',specialists:'проверенных сотрудников',step2Text:'Профессиональный сотрудник приедет со всем необходимым.'});
const original={};$$('[data-i18n]').forEach(el=>original[el.dataset.i18n]=el.textContent);
function applyHomeLanguage(lang){state.lang=lang==='ru'?'ru':'uz';window.setGoCleanLanguage?.(state.lang);document.documentElement.lang=state.lang;$('#langToggle').textContent=state.lang==='uz'?'RU':'UZ';$$('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;el.textContent=state.lang==='ru'?(ru[key]||original[key]):original[key]});calculate()}
$('#langToggle').addEventListener('click',()=>applyHomeLanguage(state.lang==='uz'?'ru':'uz'));
applyHomeLanguage(state.lang);
